import os 
from dotenv import load_dotenv

load_dotenv()

cMN = os.getenv("CLAUDE_MODEL_NAME")
cAK = os.getenv("CLAUDE_API_KEY")

import anthropic    

client = anthropic.Anthropic(api_key=cAK)

#MCP CONNECTOR WITH MESSAGES API
response = client.beta.messages.create(
    model = cMN,
    max_tokens = 1777,
    messages = [
        {
            "role": "user",
            "content": """Give me python code snippets for usage of the Microsoft Foundry SDK for the Foundry Agent Service.
            Also give citations of the web page links used to come up with the response"""
        }
    ],
    mcp_servers = [
        {
            "type": "url",
            "url": "https://learn.microsoft.com/api/mcp",
            "name": "MSLearnMCPServer"
        }
    ],
    tools = [{"type": "mcp_toolset", "mcp_server_name": "MSLearnMCPServer"}],
    betas=["mcp-client-2025-11-20"]
)


for block in response.content:
    if block.type == "text":
        print(block.text)

print(response.to_json())












